Read Sheet2 incoming quantities and sum them by Order No and item code. For each Sheet1 row, group by the same key and allocate the group’s stock in FIFO order by Order issued Date, then Line, capped by Order Qty. Write the resulting plain numbers to Sheet1!H2:H18.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta
from collections import defaultdict

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def norm_order(v):
    if v is None:
        return ""
    if isinstance(v, float) and v.is_integer():
        v = int(v)
    return str(v).strip().replace("/", "-").upper()

def norm_item(v):
    if v is None:
        return ""
    if isinstance(v, float) and v.is_integer():
        v = int(v)
    return str(v).strip().upper()

def to_num(v):
    if v is None:
        return 0.0
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().replace(",", "")
    try:
        return float(s)
    except Exception:
        return 0.0

def parse_date(v):
    if v is None:
        return datetime.max
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if isinstance(v, (int, float)):
        try:
            return datetime(1899, 12, 30) + timedelta(days=float(v))
        except Exception:
            return datetime.max
    s = str(v).strip()
    if not s:
        return datetime.max
    formats = [
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
        "%d/%m/%y",
        "%d/%m/%Y",
        "%d-%m-%Y",
        "%d-%m-%y",
        "%m/%d/%y",
        "%m/%d/%Y",
        "%Y/%m/%d",
    ]
    for fmt in formats:
        try:
            return datetime.strptime(s, fmt)
        except Exception:
            pass
    return datetime.max

def clean_num(x):
    if x is None:
        return 0
    x = float(x)
    if abs(x - round(x)) < 1e-9:
        return int(round(x))
    return round(x, 2)

# Sum available incoming stock from Sheet2 by Order No + item key.
stock = defaultdict(float)
if "Sheet2" in vals:
    ws2v = vals["Sheet2"]
    for r in range(2, ws2v.max_row + 1):
        order = norm_order(ws2v.cell(r, 1).value)
        code = norm_item(ws2v.cell(r, 2).value)
        item = norm_item(ws2v.cell(r, 3).value)
        qty = to_num(ws2v.cell(r, 4).value)

        if not order and not code and not item:
            continue

        key = (order, code if code else item)
        stock[key] += qty

# Read Sheet1 order lines.
ws1v = vals["Sheet1"]
ws1 = wb["Sheet1"]
end_row = max(18, ws1v.max_row)

rows = []
for r in range(2, end_row + 1):
    order = norm_order(ws1v.cell(r, 1).value)
    line = to_num(ws1v.cell(r, 2).value)
    issued = parse_date(ws1v.cell(r, 3).value)
    code = norm_item(ws1v.cell(r, 4).value)
    item = norm_item(ws1v.cell(r, 5).value)
    qty = to_num(ws1v.cell(r, 7).value)

    key = (order, code if code else item)
    rows.append((r, key, issued, line if line > 0 else r, qty))

# Allocate stock within each Order No + item group.
groups = defaultdict(list)
for r, key, issued, line, qty in rows:
    groups[key].append((issued, line, r, qty))

alloc = {}
for key, group in groups.items():
    remaining = stock.get(key, 0.0)
    group.sort(key=lambda x: (x[0], x[1], x[2]))

    for _, _, r, qty in group:
        if remaining <= 0:
            allocated = 0.0
        else:
            allocated = min(qty, remaining)
            if allocated < 0:
                allocated = 0.0
        remaining -= allocated
        alloc[r] = clean_num(allocated)

# Write only the graded answer region.
for r in range(2, 19):
    ws1.cell(r, 8).value = alloc.get(r, 0)

print("stock:", dict(stock))
print("alloc:", {r: alloc.get(r, 0) for r in range(2, 19)})

wb.save(OUT)
